-- connect.quantt.ca on Cloudflare D1 (SQLite).
--
-- This is the final state of supabase/migrations/0001 .. 20261101045550,
-- translated to SQLite. Postgres row-level security has no SQLite
-- equivalent: who may read or write which row lives in lib/db/policies.ts,
-- and every query goes through it. What SQLite can enforce on its own
-- (checks, uniqueness, immutable columns, system tiers) stays here.
--
-- Conventions:
--   ids         text uuid, generated by the app (crypto.randomUUID()).
--   timestamps  text ISO 8601 UTC, e.g. 2026-11-01T23:05:14.000Z, so
--               string comparison is time order.
--   dates       text YYYY-MM-DD.
--   booleans    integer 0 or 1.
--   json        text that passes json_valid().
-- Apply with: npx wrangler d1 migrations apply connect-db --remote

PRAGMA foreign_keys = ON;

-- ---------------------------------------------------------------------------
-- Sponsor packages
-- ---------------------------------------------------------------------------

CREATE TABLE sponsor_capabilities (
  key text PRIMARY KEY,
  label text NOT NULL,
  description text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('boolean', 'quota')),
  is_enforced integer NOT NULL DEFAULT 1 CHECK (is_enforced IN (0, 1)),
  sort_order integer NOT NULL DEFAULT 0
);

CREATE TABLE sponsor_tiers (
  id text PRIMARY KEY,
  key text NOT NULL UNIQUE,
  name text NOT NULL,
  rank integer NOT NULL,
  price_cents integer,
  blurb text NOT NULL DEFAULT '',
  applicant_embargo_hours integer NOT NULL DEFAULT 0
    CHECK (applicant_embargo_hours BETWEEN 0 AND 8760),
  resume_book_embargo_hours integer NOT NULL DEFAULT 0
    CHECK (resume_book_embargo_hours BETWEEN 0 AND 8760),
  is_active integer NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  is_system integer NOT NULL DEFAULT 0 CHECK (is_system IN (0, 1)),
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE UNIQUE INDEX sponsor_tiers_rank_active ON sponsor_tiers (rank) WHERE is_active = 1;

CREATE TABLE sponsor_tier_capabilities (
  tier_id text NOT NULL REFERENCES sponsor_tiers (id) ON DELETE CASCADE,
  capability text NOT NULL REFERENCES sponsor_capabilities (key),
  value integer,
  PRIMARY KEY (tier_id, capability)
);

-- ---------------------------------------------------------------------------
-- People and firms
-- ---------------------------------------------------------------------------

-- On Supabase, profiles.id was the auth.users id. Here profiles is the user
-- table itself; sign-in (PR 2) looks people up by email.
CREATE TABLE profiles (
  id text PRIMARY KEY,
  email text NOT NULL UNIQUE COLLATE NOCASE,
  full_name text NOT NULL DEFAULT '',
  role text NOT NULL CHECK (role IN ('member', 'company_user')),
  is_admin integer NOT NULL DEFAULT 0 CHECK (is_admin IN (0, 1)),
  program text,
  grad_year integer,
  bio text,
  interests text,
  linkedin_url text,
  github_url text,
  website_url text,
  photo_path text,
  resume_book_opt_in integer NOT NULL DEFAULT 0 CHECK (resume_book_opt_in IN (0, 1)),
  resume_book_opt_in_at text,
  resume_book_opt_in_by text REFERENCES profiles (id),
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CONSTRAINT admin_is_member CHECK (is_admin = 0 OR role = 'member'),
  CONSTRAINT resume_book_opt_in_is_member CHECK (resume_book_opt_in = 0 OR role = 'member')
);

CREATE TABLE companies (
  id text PRIMARY KEY,
  name text NOT NULL,
  slug text NOT NULL UNIQUE,
  logo_url text,
  website text,
  description text,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  sponsor_tier_id text NOT NULL REFERENCES sponsor_tiers (id) ON DELETE RESTRICT,
  grace_tier_id text REFERENCES sponsor_tiers (id) ON DELETE RESTRICT,
  tier_grace_until text,
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX companies_sponsor_tier_idx ON companies (sponsor_tier_id);

CREATE TABLE company_capability_overrides (
  company_id text NOT NULL REFERENCES companies (id) ON DELETE CASCADE,
  capability text NOT NULL REFERENCES sponsor_capabilities (key),
  granted integer NOT NULL CHECK (granted IN (0, 1)),
  value integer,
  PRIMARY KEY (company_id, capability)
);

CREATE TABLE company_users (
  company_id text NOT NULL REFERENCES companies (id) ON DELETE CASCADE,
  profile_id text NOT NULL UNIQUE REFERENCES profiles (id) ON DELETE CASCADE,
  PRIMARY KEY (company_id, profile_id)
);

CREATE TABLE invites (
  id text PRIMARY KEY,
  email text NOT NULL,
  full_name text NOT NULL DEFAULT '',
  role text NOT NULL CHECK (role IN ('member', 'company_user')),
  is_admin integer NOT NULL DEFAULT 0 CHECK (is_admin IN (0, 1)),
  company_id text REFERENCES companies (id) ON DELETE CASCADE,
  invited_by text REFERENCES profiles (id),
  accepted_at text,
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CONSTRAINT company_invite_has_company CHECK (
    (role = 'company_user' AND company_id IS NOT NULL)
    OR (role = 'member' AND company_id IS NULL)
  )
);

CREATE UNIQUE INDEX invites_pending_email ON invites (lower(email)) WHERE accepted_at IS NULL;

CREATE TABLE company_join_requests (
  id text PRIMARY KEY,
  company_name text NOT NULL CHECK (length(company_name) BETWEEN 1 AND 200),
  website text CHECK (website IS NULL OR length(website) <= 500),
  contact_name text NOT NULL CHECK (length(contact_name) BETWEEN 1 AND 120),
  contact_email text NOT NULL CHECK (length(contact_email) BETWEEN 3 AND 254),
  note text CHECK (note IS NULL OR length(note) <= 2000),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
  reviewed_by text REFERENCES profiles (id),
  reviewed_at text,
  admin_note text,
  company_id text REFERENCES companies (id),
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE UNIQUE INDEX join_requests_pending_email
  ON company_join_requests (lower(contact_email)) WHERE status = 'pending';

-- Fixed-window rate limits for the public join form (submit_join_request).
CREATE TABLE join_admission (
  key text PRIMARY KEY,
  used integer NOT NULL,
  expires_at text NOT NULL
);

CREATE INDEX join_admission_expires_at_idx ON join_admission (expires_at);

-- ---------------------------------------------------------------------------
-- Member documents
-- ---------------------------------------------------------------------------

CREATE TABLE profile_sections (
  id text PRIMARY KEY,
  member_id text NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  label text NOT NULL,
  body text NOT NULL,
  sort_order integer NOT NULL DEFAULT 0
);

CREATE INDEX profile_sections_member_id_idx ON profile_sections (member_id);

CREATE TABLE hiring_packages (
  id text PRIMARY KEY,
  member_id text NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  name text NOT NULL,
  linkedin_url text NOT NULL,
  resume_path text NOT NULL,
  cover_letter text,
  cover_letter_path text,
  is_default integer NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX hiring_packages_member_id_idx ON hiring_packages (member_id);
CREATE UNIQUE INDEX hiring_packages_one_default ON hiring_packages (member_id) WHERE is_default = 1;

CREATE TABLE member_documents (
  member_id text PRIMARY KEY REFERENCES profiles (id) ON DELETE CASCADE,
  resume_path text,
  cover_letter_path text,
  cover_letter text CHECK (cover_letter IS NULL OR length(cover_letter) <= 4000),
  updated_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- ---------------------------------------------------------------------------
-- Posts, applications, messages
-- ---------------------------------------------------------------------------

CREATE TABLE posts (
  id text PRIMARY KEY,
  author_id text NOT NULL REFERENCES profiles (id) ON DELETE RESTRICT,
  company_id text REFERENCES companies (id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('job', 'event', 'announcement', 'connection', 'job_link')),
  title text NOT NULL,
  body text NOT NULL DEFAULT '',
  location text,
  starts_at text,
  published integer NOT NULL DEFAULT 1 CHECK (published IN (0, 1)),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  role_type text CHECK (role_type IN ('full_time', 'internship', 'coop')),
  term_season text CHECK (term_season IN ('fall', 'winter', 'summer')),
  term_year integer,
  external_url text,
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CONSTRAINT in_app_job_fields CHECK (
    kind <> 'job'
    OR external_url IS NOT NULL
    OR (role_type IS NOT NULL AND term_season IS NOT NULL AND term_year IS NOT NULL)
  ),
  CONSTRAINT job_link_has_url CHECK (kind <> 'job_link' OR external_url IS NOT NULL)
);

CREATE INDEX posts_company_id_idx ON posts (company_id);
CREATE INDEX posts_published_created_idx ON posts (created_at DESC) WHERE published = 1;

CREATE TABLE post_comments (
  id text PRIMARY KEY,
  post_id text NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  author_id text NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  body text NOT NULL,
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX post_comments_post_id_idx ON post_comments (post_id);

CREATE TABLE applications (
  id text PRIMARY KEY,
  member_id text NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('in_app', 'off_platform')),
  post_id text REFERENCES posts (id) ON DELETE CASCADE,
  company_id text REFERENCES companies (id),
  company_name text,
  package_id text REFERENCES hiring_packages (id) ON DELETE SET NULL,
  package_name text,
  linkedin_url text,
  resume_path text,
  cover_letter text,
  cover_letter_path text,
  stage text NOT NULL DEFAULT 'submitted'
    CHECK (stage IN ('submitted', 'reviewing', 'interviewing', 'offer', 'closed')),
  notes text,
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CONSTRAINT in_app_needs_post CHECK (kind <> 'in_app' OR post_id IS NOT NULL),
  CONSTRAINT off_platform_needs_name CHECK (kind <> 'off_platform' OR company_name IS NOT NULL),
  CONSTRAINT in_app_snapshot_paths CHECK (
    kind <> 'in_app' OR (
      resume_path IN ('snapshots/' || id || '/resume.pdf', 'snapshots/' || id || '/cover.pdf')
      AND (cover_letter_path IS NULL
        OR cover_letter_path IN ('snapshots/' || id || '/resume.pdf', 'snapshots/' || id || '/cover.pdf'))
    )
  )
);

CREATE INDEX applications_company_id_idx ON applications (company_id);
CREATE INDEX applications_member_id_idx ON applications (member_id);
CREATE INDEX applications_post_id_idx ON applications (post_id);
CREATE UNIQUE INDEX applications_one_per_job ON applications (member_id, post_id) WHERE post_id IS NOT NULL;

CREATE TABLE conversations (
  id text PRIMARY KEY,
  member_id text NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  company_id text NOT NULL REFERENCES companies (id) ON DELETE CASCADE,
  member_last_read_at text,
  company_last_read_at text,
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (member_id, company_id)
);

CREATE INDEX conversations_company_id_idx ON conversations (company_id);

CREATE TABLE messages (
  id text PRIMARY KEY,
  conversation_id text NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  sender_id text NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  body text NOT NULL,
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX messages_conversation_id_idx ON messages (conversation_id, created_at);

CREATE TABLE sponsor_tier_events (
  id text PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN (
    'tier_created', 'tier_updated', 'tier_deactivated', 'tier_reactivated',
    'capability_granted', 'capability_revoked', 'company_assigned',
    'company_access', 'company_status'
  )),
  tier_id text REFERENCES sponsor_tiers (id) ON DELETE SET NULL,
  company_id text REFERENCES companies (id) ON DELETE SET NULL,
  detail text NOT NULL DEFAULT '{}' CHECK (json_valid(detail)),
  actor_id text REFERENCES profiles (id),
  created_at text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX sponsor_tier_events_created_idx ON sponsor_tier_events (created_at DESC);

-- ---------------------------------------------------------------------------
-- Triggers: invariants that hold no matter who writes
-- ---------------------------------------------------------------------------

-- applications_snapshot_immutable: what was sent to a firm never changes.
CREATE TRIGGER applications_snapshot_immutable
BEFORE UPDATE ON applications
WHEN NEW.package_name IS NOT OLD.package_name
  OR NEW.linkedin_url IS NOT OLD.linkedin_url
  OR NEW.resume_path IS NOT OLD.resume_path
  OR NEW.cover_letter IS NOT OLD.cover_letter
  OR NEW.cover_letter_path IS NOT OLD.cover_letter_path
  OR NEW.post_id IS NOT OLD.post_id
  OR NEW.member_id IS NOT OLD.member_id
  OR NEW.kind IS NOT OLD.kind
  OR NEW.company_id IS NOT OLD.company_id
  OR NEW.package_id IS NOT OLD.package_id
BEGIN
  SELECT RAISE(ABORT, 'Application snapshot cannot be changed');
END;

CREATE TRIGGER applications_touch
AFTER UPDATE ON applications
WHEN NEW.updated_at IS OLD.updated_at
BEGIN
  UPDATE applications SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = NEW.id;
END;

-- conversations_protect_keys: participants are fixed (read receipts only).
CREATE TRIGGER conversations_protect_keys
BEFORE UPDATE ON conversations
WHEN NEW.member_id IS NOT OLD.member_id OR NEW.company_id IS NOT OLD.company_id
BEGIN
  SELECT RAISE(ABORT, 'Conversation participants cannot be changed');
END;

-- hiring_packages_default_guard: one default per member.
CREATE TRIGGER hiring_packages_default_insert
BEFORE INSERT ON hiring_packages
WHEN NEW.is_default = 1
BEGIN
  UPDATE hiring_packages SET is_default = 0 WHERE member_id = NEW.member_id AND is_default = 1;
END;

CREATE TRIGGER hiring_packages_default_update
BEFORE UPDATE OF is_default ON hiring_packages
WHEN NEW.is_default = 1 AND OLD.is_default = 0
BEGIN
  UPDATE hiring_packages SET is_default = 0
    WHERE member_id = NEW.member_id AND id <> NEW.id AND is_default = 1;
END;

CREATE TRIGGER hiring_packages_touch
AFTER UPDATE ON hiring_packages
WHEN NEW.updated_at IS OLD.updated_at
BEGIN
  UPDATE hiring_packages SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = NEW.id;
END;

-- sponsor_tiers_guard: the none and grandfathered tiers always exist.
CREATE TRIGGER sponsor_tiers_system_delete
BEFORE DELETE ON sponsor_tiers
WHEN OLD.is_system = 1
BEGIN
  SELECT RAISE(ABORT, 'This tier is required and cannot be deleted');
END;

CREATE TRIGGER sponsor_tiers_system_update
BEFORE UPDATE ON sponsor_tiers
WHEN OLD.is_system = 1 AND (NEW.key IS NOT OLD.key OR NEW.is_active IS NOT OLD.is_active)
BEGIN
  SELECT RAISE(ABORT, 'This tier cannot change its key or active flag');
END;

-- profiles_stamp_opt_in (the part that does not depend on who is writing):
-- turning consent off clears the stamp. Turning it on is stamped by the app
-- with the member's own id (lib/db/policies.ts, stampOptIn).
CREATE TRIGGER profiles_opt_out_clears_stamp
AFTER UPDATE OF resume_book_opt_in ON profiles
WHEN NEW.resume_book_opt_in = 0
  AND (NEW.resume_book_opt_in_at IS NOT NULL OR NEW.resume_book_opt_in_by IS NOT NULL)
BEGIN
  UPDATE profiles SET resume_book_opt_in_at = NULL, resume_book_opt_in_by = NULL WHERE id = NEW.id;
END;
